import libtmux, time
try:
    srv=libtmux.Server()
    print("tmux server ok")
except Exception as e:
    print("tmux err",e)
    raise SystemExit
def run_tmux(name, cmds, cwd, inputs):
    # cmds: shell cmd string; inputs: list of (delay, send_str)
    try: srv.kill_session(name)
    except: pass
    sess=srv.new_session(session_name=name, kill_session=True, start_directory=cwd)
    win=sess.windows[0]
    pane=win.panes[0]
    pane.send_keys(cmds, enter=True)
    out=[]
    for delay,s in inputs:
        time.sleep(delay)
        try: out.append("\n".join(pane.capture_pane()))
        except Exception as e: out.append(f"<capture err {e}>")
        if s is not None:
            pane.send_keys(s, enter=False, literal=True)
    time.sleep(0.8)
    try: out.append("FINAL:\n"+"\n".join(pane.capture_pane()))
    except Exception as e: out.append(str(e))
    try: srv.kill_session(name)
    except: pass
    print(f"=== {name} cmd={cmds} ===")
    for i,o in enumerate(out): print(f"---snap {i}---\n{o}")
    print()

