                elif code=='r':
                    out+=dt.strftime("%I:%M:%S %p")
                elif code=='v':
                    out+=f"{dt.day:2d}-{dt.strftime('%b')}-{dt.strftime('%Y')}"
                elif code=='h':
                    out+=dt.strftime("%b")
                elif code=='C':
                    out+=f"{dt.year//100:02d}"
                elif code=='g':
                    out+=dt.strftime("%y")  # ISO year approx
                elif code=='G':
                    out+=str(dt.isocalendar()[0])
                elif code=='u':
