    Raises TemplateParseError or TemplateRenderError for fatal cases (date helper, join arity, render errors)."""
    check_template(tmpl)
    nodes,_,_= _parse_nodes(tmpl)
    state=EvalState(lang=lang)
    root=context
    ctx_stack=[context]
    data_stack=[{}]
    # @root/@env handled in resolve
    out=_render_nodes(nodes, ctx_stack, data_stack, root, state, tmpl)
    return out, state.warnings

