# Template renderer
class TemplateRenderError(Exception):
    def __init__(self, msg, node_desc=None):
        self.msg=msg; self.node_desc=node_desc

def _is_truthy(v):
    if v is None: return False
    if isinstance(v, bool): return v
    if isinstance(v, (int,float)): return v!=0
    if isinstance(v, str): return len(v)>0
    if isinstance(v, (list,tuple,dict)): return len(v)>0
    return True

def _parse_nodes(tmpl, pos=0, end_block=None):
    """Parse template into nodes. Returns (nodes, next_pos, closing_name)
    Node types: ('text',s), ('var',expr,raw_triple), ('block',name,expr,body,else_body)
    """
    nodes=[]
    i=pos
    while i < len(tmpl):
        start=tmpl.find('{{', i)
        if start==-1:
            nodes.append(('text', tmpl[i:]))
            return nodes, len(tmpl), None
        if start>i:
            nodes.append(('text', tmpl[i:start]))
        triple=tmpl.startswith('{{{', start)
        if triple:
            end=tmpl.find('}}}', start+3)
            if end==-1:
                raise TemplateParseError('Parse error on line 1:\n           Lexer error\n           Token: Error{"Unclosed expression"}')
            expr=tmpl[start+3:end].strip()
            # {{{title}}} in raymond parses as helper? Observed gave results in different order (maybe {{{title}}} == {{ {title} }}?). Treat as raw var of inner stripped of braces?
            # Actually expr here is 'title' if triple correct.
            nodes.append(('var', expr, True))
            i=end+3
            continue
        end=tmpl.find('}}', start+2)
        if end==-1:
            single=tmpl.find('}', start+2)
            if single!=-1:
                raise TemplateParseError('Parse error on line 1:\n           Lexer error\n           Token: Error{"Unexpected character in expression: \'}\'"}')
            raise TemplateParseError('Parse error on line 1:\n           Lexer error\n           Token: Error{"Unclosed expression"}')
        expr_raw=tmpl[start+2:end]
        expr=expr_raw.strip()
        # Handlebars comments {{!-- ... --}} and {{! ... }}
        if expr.startswith('!'):
            i=end+2
            continue
        if expr.startswith('#'):
            # block start
            block_expr=expr[1:].strip()
            # first word is block name
            # parse body until else or close
            body, after, closing = _parse_until(tmpl, end+2, block_expr)
            nodes.append(('block', block_expr, body[0], body[1]))
            i=after
            continue
        elif expr.startswith('/'):
            # handled by _parse_until; if at top level -> error in check
            return nodes, end+2, expr[1:].strip()
        elif expr=='else':
            return nodes, end+2, 'else'
        else:
            # '{{{' single brace inside normal? '{{{title}}}' raw case: tmpl starts '{{{' but end find '}}}' handled above. What about '{{{title}}}' with triple open but only double close? Then expr would be '{title' ??? Ignore.
            nodes.append(('var', expr, False))
            i=end+2
            continue
    return nodes, len(tmpl), None

def _parse_until(tmpl, pos, block_expr):
    """Parse body of a block starting at pos, handling else. Returns ((body_nodes, else_nodes), after_pos, closing)"""
    body_nodes=[]
    else_nodes=[]
    current='body'
    i=pos
    # block name for matching close (first token)
    block_name=block_expr.split()[0] if block_expr.split() else ""
    while i < len(tmpl):
        start=tmpl.find('{{', i)
        if start==-1:
            (body_nodes if current=='body' else else_nodes).append(('text', tmpl[i:]))
            return (body_nodes, else_nodes), len(tmpl), None
        if start>i:
            (body_nodes if current=='body' else else_nodes).append(('text', tmpl[i:start]))
        triple=tmpl.startswith('{{{', start)
        if triple:
            end=tmpl.find('}}}', start+3)
            if end==-1:
                raise TemplateParseError('Parse error on line 1:\n           Lexer error\n           Token: Error{"Unclosed expression"}')
            expr=tmpl[start+3:end].strip()
            (body_nodes if current=='body' else else_nodes).append(('var', expr, True))
            i=end+3
            continue
        end=tmpl.find('}}', start+2)
        if end==-1:
            raise TemplateParseError('Parse error on line 1:\n           Lexer error\n           Token: Error{"Unclosed expression"}')
        expr=tmpl[start+2:end].strip()
        if expr.startswith('#'):
            inner_body, after, _ = _parse_until(tmpl, end+2, expr[1:].strip())
            (body_nodes if current=='body' else else_nodes).append(('block', expr[1:].strip(), inner_body[0], inner_body[1]))
            i=after
            continue
        elif expr.startswith('/'):
            return (body_nodes, else_nodes), end+2, expr[1:].strip()
        elif expr=='else':
            current='else'
            i=end+2
            continue
        elif expr.startswith('!'):
            i=end+2; continue
        else:
            (body_nodes if current=='body' else else_nodes).append(('var', expr, False))
            i=end+2
            continue
    return (body_nodes, else_nodes), len(tmpl), None

