def eval_expr(expr, ctx_stack, data_stack, root, state):
    """Evaluate a handlebars expression (for {{ ... }}). Returns value.
    Handles: single path, literals (resolve to missing unless helper arg), helper calls, subexpressions (basic)."""
    expr=expr.strip()
    if expr=="":
        return None
    tokens=tokenize_handlebars_expr(expr)
    if not tokens:
        return None
    # Helper detection
    # If first token is a known helper name and there are arguments -> helper call
    # Known helpers: format-date, date (fatal), slug, join, prepend, lookup, log, word-count
    # Unknown helpers with args return None (observed).
    # Subexpressions: token sequence like (eq title 'x') -> evaluate subexpr; eq unknown returns None.
    val, consumed = _eval_tokens(tokens, 0, ctx_stack, data_stack, root, state)
    return val

