def group_note_config(cfg, group):
    """Return effective NoteConfig for group (clone base + overrides)"""
    nc=cfg.note.clone()
    if group is None:
        return nc, dict(cfg.extra)
    ov=group.note_overrides
    if 'language' in ov: nc.language=ov['language']
    if 'default-title' in ov: nc.default_title=ov['default-title']
    if 'filename' in ov: nc.filename=ov['filename']
    if 'extension' in ov: nc.extension=ov['extension']
    if 'template' in ov: nc.template=ov['template']
    if 'exclude' in ov: nc.exclude=list(ov['exclude'])
    if 'id-charset' in ov: nc.id_charset=ov['id-charset']
    if 'id-length' in ov: nc.id_length=ov['id-length']
    if 'id-case' in ov: nc.id_case=ov['id-case']
    extra=dict(cfg.extra); extra.update(group.extra_overrides)
    return nc, extra

def find_group_for_dir(cfg, rel_dir):
    """rel_dir: relative posix dir from notebook root ('' for root, 'journal', 'journal/sub')
    Returns GroupConfig or None. Matching: paths entries; if rel_dir == path or rel_dir under path; glob support for path containing * via fnmatch on rel_dir (observed a/* matched a/b not a)."""
    if rel_dir is None: return None
    rel = rel_dir.strip('/')
    for name, gc in cfg.groups.items():
        paths = gc.paths if gc.paths is not None else [name]
        for p in paths:
            pp=p.strip('/')
            if '*' in pp or '?' in pp or '[' in pp:
                if fnmatch.fnmatch(rel, pp):
                    return gc
            else:
                if rel==pp or rel.startswith(pp+'/'):
                    return gc
    return None

