        rows=list(con.execute("SELECT rowid, rank, snippet(notes_fts, 2, '', '', '…', 20) FROM notes_fts WHERE notes_fts MATCH ? ORDER BY rank", (q,)))
        return rows
    try:
        rows=do_match(query)
    except sqlite3.Error:
        # sanitize
        terms=re.findall(r'[^\s]+', query)
        # Keep boolean operators OR AND NOT, column filters xxx: , quoted phrases, prefix *
        # Build safer query: extract word characters sequences with unicode.
        # If original had OR, preserve OR between tokens; default AND (space)
        # Simpler: replace characters that are FTS syntax problematic (. etc) with space, keep * " : parentheses?
        cleaned=re.sub(r'[.]', ' ', query)
        # single quotes around phrase: reference "'quick brown'" (single quotes) gave no match (FTS phrase needs double). Keeping single quotes in FTS: tokenizer chars include '' tokenchar, word includes quotes -> no match likely. So don't transform single quoted.
        try:
            rows=do_match(cleaned)
        except sqlite3.Error:
            # last resort: tokens AND
            toks=re.findall(r'[\wÀ-ÿ\'&/]+', query, flags=re.UNICODE)
            if not toks:
                return [], {}, {}
            q2=' '.join(toks)
            try:
                rows=do_match(q2)
            except sqlite3.Error:
                return [], {}, {}
    ids=[]; ranks={}; snips={}
    for rowid, rank, snip in rows:
        ids.append(rowid); ranks[rowid]=rank; snips[rowid]=snip if snip is not None else ""
    return ids, ranks, snips

