def generate_id(note_cfg):
    charset_raw=note_cfg.id_charset
    length=note_cfg.id_length if note_cfg.id_length and note_cfg.id_length>0 else 4
    if note_cfg.id_length and note_cfg.id_length<0:
        # Reference panics; callers in new should trigger panic output. Raise special.
        raise _PanicIDLength()
    # charset mapping
    if charset_raw=="" or charset_raw is None:
        charset="abcdefghijklmnopqrstuvwxyz0123456789"  # alphanum default
        # But observed empty string id-charset="" gave ids like 'fehg','ZC76','PMLP' depending on case; all letters upper/lower - sampling gives mostly letters as alphanum set has 26 letters vs 10 digits, plausible.
    elif charset_raw=="letters":
        charset="abcdefghijklmnopqrstuvwxyz"
    elif charset_raw=="numbers":
        charset="0123456789"
    elif charset_raw=="alphanum":
        charset="abcdefghijklmnopqrstuvwxyz0123456789"
    elif charset_raw=="hex":
        charset="abcdef0123456789"
    else:
        charset=charset_raw
    case=(note_cfg.id_case or "lower").lower()
    # For mixed, generator likely builds charset case variants: for 'xyz' mixed results included 'X' uppercase randomly. Model: if mixed, charset expands to lower+upper variants (unique preserving). If upper, output upper; lower output lower; invalid case observed gave lower (s001 - letters lower) so default lower.
    if case=='upper':
        eff_charset=charset.upper()
    elif case=='mixed':
        # combine
        eff=""
        for c in charset:
            if c.lower() not in eff.lower():
                eff+=c.lower()+c.upper() if c.isalpha() else c
            # approximate: need both cases available
        # Simplify: eff charset = charset.lower()+charset.upper() dedup digits once
        eff_charset=""
        for c in charset.lower()+charset.upper():
