def uri_to_path(uri):
    if not uri: return ""
    if uri.startswith('file://'):
        p=urllib.parse.urlparse(uri).path
        return urllib.parse.unquote(p)
    return uri

def position_to_offset(text, line, character):
    lines=text.splitlines(keepends=True)
    off=0
    for i,l in enumerate(lines):
        if i==line:
            # character is UTF-16 code units in LSP; approximating Python chars (tests likely ascii)
            return off+character
        off+=len(l)
    return off

def offset_to_pos(text, offset):
    prefix=text[:offset]
    line=prefix.count('\n')
    last=prefix.rfind('\n')
    char=offset-(last+1) if last!=-1 else offset
    return {"line":line,"character":char}

def offset_to_range(text,start,end):
    return {"start":offset_to_pos(text,start),"end":offset_to_pos(text,end)}

def link_range_in_text(text, link):
    """Find approximate range of link markup in text (first occurrence after snippet_start clue?). Our link dict snippet_start is block start in raw (if doc is file content, same). Search starting near snippet_start."""
    href=link.get('href') or ""
    typ=link.get('type')
    patterns=[]
    if typ=='wiki-link':
        patterns=[f"[[{href}", f"[[{link.get('title','')}"]
        # generic [[...]] occurrences in order - we cannot identify which specific, rely on sequential scanning by caller? Diagnostics order sequential search from 0 would always first. Accept for single-link docs typical.
        m=re.search(r'\[\[[^\]]+\]\]', text)
        if not m: return None
        # Find occurrence whose inner starts with href or alias
        for mm in re.finditer(r'\[\[([^\]]+)\]\]', text):
            inner=mm.group(1)
            if inner.split('|',1)[0].strip()==href or inner.strip()==href:
                return offset_to_range(text, mm.start(), mm.end())
        return offset_to_range(text,m.start(),m.end())
    elif typ=='markdown':
        for mm in re.finditer(r'\[[^\]]*\]\([^)]*\)', text):
            if href in mm.group(0):
                return offset_to_range(text,mm.start(),mm.end())
        return None
    else:
        idx=text.find(href)
        if idx==-1: return None
        return offset_to_range(text,idx,idx+len(href))

def apply_lsp_change(text, ch):
    rng=ch.get('range') or {}
    start=rng.get('start') or {}; end=rng.get('end') or {}
    s=position_to_offset(text,start.get('line',0),start.get('character',0))
    e=position_to_offset(text,end.get('line',0),end.get('character',0))
    return text[:s]+ch.get('text','')+text[e:]

