# ---------------------------------------------------------------- LSP (basic)
def cmd_lsp(parsed, ctx):
    # Reference LSP: reads headers Content-Length with \n line endings? It emits "Content-Length: 469\n\n{...}" (LF not CRLF). Our Python should emit similar for initialize/shutdown, handle basic requests.
    # Notebook may or may not exist at server start; initialize still succeeds (rootUri used to find notebook after). If ctx has notebook, use it; otherwise documents root from initialize rootUri/rootPath/workspaceFolders will be used when needed.
    server=LSPServer(ctx)
